#include <stdio.h>
#include <math.h>
#include <float.h>

int main(){
    double train[6][2] = {{1,2},{2,3},{3,1},{4,5},{5,4},{5,6}};
    char label[6] = {'A','A','A','B','B','B'};
    double qx=3, qy=4;
    double d[6];
    for(int i=0;i<6;i++){
        double dx = train[i][0]-qx;
        double dy = train[i][1]-qy;
        d[i] = sqrt(dx*dx + dy*dy);
    }
    // find three smallest distances
    int idx[3] = {-1,-1,-1};
    for(int i=0;i<6;i++){
        // insert d[i] into idx if it belongs to the three smallest
        for(int j=0;j<3;j++){
            if(idx[j]==-1 || d[i] < d[idx[j]]){
                // shift larger entries right
                for(int k=2;k>j;k--) idx[k]=idx[k-1];
                idx[j]=i;
                break;
            }
        }
    }
    double wA=0,wB=0;
    for(int i=0;i<3;i++){
        double weight = 1.0/d[idx[i]];
        if(label[idx[i]]=='A') wA+=weight; else wB+=weight;
    }
    printf("Weight A = %.3f\n", wA);
    printf("Weight B = %.3f\n", wB);
    printf("Prediction = %c\n", (wB>wA)?'B':'A');
    return 0;
}
